import crypto from 'node:crypto'

export interface AuthedRequest {
  headers?: Record<string, string | string[] | undefined>
}

/**
 * Verifies the HMAC-SHA256 Bearer token generated by /api/auth/login.
 * Tokens remain valid for 24 hours.
 */
export function verifyAdminToken(req: AuthedRequest): boolean {
  const authHeader = req.headers?.authorization
  const headerValue = Array.isArray(authHeader) ? authHeader[0] : authHeader
  if (!headerValue || !headerValue.startsWith('Bearer ')) return false

  const token = headerValue.slice('Bearer '.length).trim()
  const dotIdx = token.indexOf('.')
  if (dotIdx <= 0) return false

  const issuedAtStr = token.slice(0, dotIdx)
  const signatureHex = token.slice(dotIdx + 1)
  const issuedAt = Number(issuedAtStr)
  if (!Number.isFinite(issuedAt)) return false

  const maxAgeMs = 24 * 60 * 60 * 1000
  if (Date.now() - issuedAt > maxAgeMs || issuedAt > Date.now() + 60_000) {
    return false
  }

  const email = (process.env.ADMIN_EMAIL || 'admin@blvrsmedia.com').trim().toLowerCase()
  const secret = process.env.CRON_SECRET || 'blvrs-admin-secret'
  const expectedSig = crypto
    .createHmac('sha256', secret)
    .update(`${email}:${issuedAtStr}`)
    .digest('hex')

  const bufProvided = Buffer.from(signatureHex, 'utf8')
  const bufExpected = Buffer.from(expectedSig, 'utf8')
  if (bufProvided.length !== bufExpected.length) return false

  return crypto.timingSafeEqual(bufProvided, bufExpected)
}
